import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline
cuda_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_fp16.h>
#include <cuda_runtime.h>
#include <math.h>
#include <float.h>
#define D 1024
#define BLOCK_M 64
#define BLOCK_N 64
#define D_TILE 128
__global__ void flash_attention_kernel(
    const half* __restrict__ Q,
    const half* __restrict__ K,
    const half* __restrict__ V,
    half* __restrict__ O,
    int B, int H, int S, float scale)
{
    int bh = blockIdx.x;
    int b = bh / H;
    int h = bh % H;
    int m_tile = blockIdx.y * BLOCK_M;
    int tid = threadIdx.x;
    int row = m_tile + tid;
    const size_t bh_off = (size_t)(b * H + h) * (size_t)S * (size_t)D;
    const half* Kbase = K + bh_off;
    const half* Vbase = V + bh_off;
    __shared__ half sTile[BLOCK_N][D_TILE];
    half q_reg[D];
    float acc[D];
    if (row < S) {
        const half* Qrow = Q + bh_off + (size_t)row * D;
        #pragma unroll 4
        for (int d = 0; d < D; d++) {
            q_reg[d] = Qrow[d];
            acc[d] = 0.0f;
        }
    }
    float m_i = -FLT_MAX;
    float l_i = 0.0f;
    for (int n0 = 0; n0 < S; n0 += BLOCK_N) {
        int n_count = min(BLOCK_N, S - n0);
        float scores[BLOCK_N];
        for (int j = 0; j < BLOCK_N; j++) scores[j] = 0.0f;
        // ---- Phase 1: Q @ K^T over D in chunks, staged through smem ----
        for (int d0 = 0; d0 < D; d0 += D_TILE) {
            for (int idx = tid; idx < n_count * D_TILE; idx += BLOCK_M) {
                int jj = idx / D_TILE;
                int dd = idx % D_TILE;
                sTile[jj][dd] = Kbase[(size_t)(n0 + jj) * D + d0 + dd];
            }
            __syncthreads();
            if (row < S) {
                for (int j = 0; j < n_count; j++) {
                    float partial = 0.0f;
                    #pragma unroll 4
                    for (int dd = 0; dd < D_TILE; dd++) {
                        partial += __half2float(q_reg[d0 + dd]) * __half2float(sTile[j][dd]);
                    }
                    scores[j] += partial;
                }
            }
            __syncthreads();
        }
        float p[BLOCK_N];
        if (row < S) {
            float m_new = m_i;
            for (int j = 0; j < n_count; j++) {
                scores[j] *= scale;
                if (scores[j] > m_new) m_new = scores[j];
            }
            float alpha = expf(m_i - m_new);
            l_i *= alpha;
            #pragma unroll 4
            for (int d = 0; d < D; d++) acc[d] *= alpha;
            for (int j = 0; j < n_count; j++) {
                p[j] = expf(scores[j] - m_new);
                l_i += p[j];
            }
            m_i = m_new;
        }
        // ---- Phase 2: P @ V over D in chunks, staged through smem ----
        for (int d0 = 0; d0 < D; d0 += D_TILE) {
            for (int idx = tid; idx < n_count * D_TILE; idx += BLOCK_M) {
                int jj = idx / D_TILE;
                int dd = idx % D_TILE;
                sTile[jj][dd] = Vbase[(size_t)(n0 + jj) * D + d0 + dd];
            }
            __syncthreads();
            if (row < S) {
                for (int j = 0; j < n_count; j++) {
                    float pj = p[j];
                    #pragma unroll 4
                    for (int dd = 0; dd < D_TILE; dd++) {
                        acc[d0 + dd] += pj * __half2float(sTile[j][dd]);
                    }
                }
            }
            __syncthreads();
        }
    }
    if (row < S) {
        half* Orow = O + bh_off + (size_t)row * D;
        float inv_l = 1.0f / l_i;
        #pragma unroll 4
        for (int d = 0; d < D; d++) {
            Orow[d] = __float2half(acc[d] * inv_l);
        }
    }
}
torch::Tensor flash_attention_forward(torch::Tensor Q, torch::Tensor K, torch::Tensor V) {
    TORCH_CHECK(Q.is_cuda() && K.is_cuda() && V.is_cuda(), "Q, K, V must be CUDA tensors");
    TORCH_CHECK(Q.dtype() == torch::kFloat16 && K.dtype() == torch::kFloat16 && V.dtype() == torch::kFloat16,
                "Q, K, V must be fp16");
    TORCH_CHECK(Q.dim() == 4 && K.dim() == 4 && V.dim() == 4, "Q, K, V must be 4D");
    TORCH_CHECK(Q.is_contiguous() && K.is_contiguous() && V.is_contiguous(), "Q, K, V must be contiguous");
    TORCH_CHECK(Q.sizes() == K.sizes() && Q.sizes() == V.sizes(), "Q, K, V must have matching shapes");
    int B = Q.size(0);
    int H = Q.size(1);
    int S = Q.size(2);
    int Dh = Q.size(3);
    TORCH_CHECK(Dh == D, "This kernel is specialized for head_dim = 1024");
    auto O = torch::empty_like(Q);
    float scale = 1.0f / sqrtf((float)Dh);
    dim3 grid(B * H, (S + BLOCK_M - 1) / BLOCK_M);
    dim3 block(BLOCK_M);
    flash_attention_kernel<<<grid, block>>>(
        reinterpret_cast<const half*>(Q.data_ptr<at::Half>()),
        reinterpret_cast<const half*>(K.data_ptr<at::Half>()),
        reinterpret_cast<const half*>(V.data_ptr<at::Half>()),
        reinterpret_cast<half*>(O.data_ptr<at::Half>()),
        B, H, S, scale);
    return O;
}
